nt_rate=round(float(self._queue.qsize()) / QUEUE_SIZE, 4), # Backpressure vulnerability proxy             delinquency_rate=telemetry.risk_score,             engagement_rate=max(0.0, 1.0 - telemetry.risk_score),             staffing_level=float(WORKER_COUNT)         )     # ========================================================     # EXECUTION ENTRYPOINT WITH REAL-TIME FEEDBACK LOOP     # ========================================================     async def execute(self, input_data: str) -> dict:         self.start_workers()         start = time.perf_counter()         policy = self.evaluate_policy(input_data)         self._dashboard.record_request(policy.risk_score)         if not policy.allowed:             self._dashboard.record_reject()             return {                 "status": 400,                 "error": policy.status,                 "risk_score": policy.risk_score             }         telemetry = await self.generate_telemetry(input_data, policy.risk_score)         future: asyncio.Future = asyncio.get_event_loop().create_future()         job = AttestationJob(payload=input_data, telemetry=telemetry, result_future=future)         if self._queue.full():             await asyncio.sleep(self._apply_backpressure())         await self._queue.put(job)         forensic_sig, auth_tag = await future         runtime_ms = (time.perf_counter() - start) * 1000         self._dashboard.record_latency(runtime_ms)         # Execution Feedback Loop: Generate snapshot and run analytical intelligence         snapshot = self._generate_operational_snapshot(telemetry)         intelligence_report = self.dois.ingest(snapshot)         result = ExecutionResult(             status=200,             session_id=f"DPR-{secrets.token_hex(4).upper()}",             telemetry=asdict(telemetry),             forensic_sig=forensic_sig,             auth_tag=auth_tag,             runtime_ms=round(runtime_ms, 4),             intelligence_report=asdict(intelligence_report)         )         logger.info(             "session=%s runtime_ms=%s queue=%s executive_confidence=%s",             result.session_id,             result.runtime_ms,             self._queue.qsize(),             intelligence_report.executive_summary[0]         )         return asdict(result)     def metrics(self) -> dict:         return self._dashboard.snapshot()                      merge with from __future__ import annotations import asyncio import hashlib import hmac import logging import secrets import time from dataclasses import asdict, dataclass from typing import Final, Deque from collections import deque # ============================================================ # LOGGING # ============================================================ logging.basicConfig(     level=logging.INFO,     format="%(asctime)s - DPR_CORE - %(levelname)s - %(message)s" ) logger = logging.getLogger(__name__) # ============================================================ # CONSTANTS # ============================================================ DEFAULT_BUDGET_MS: Final[float] = 42.0 MAX_RISK_THRESHOLD: Final[float] = 0.80 LONG_PAYLOAD_THRESHOLD: Final[int] = 500 EPOCH_WINDOW_SECONDS: Final[int] = 60 IDENTITY_TOKENS: Final[set[str]] = {"i", "me", "my", "we", "us", "our"} COURTESY_TOKENS: Final[set[str]] = {     "please", "could", "helpful", "assistant", "help" } IDENTITY_WEIGHT: Final[float] = 0.15 COURTESY_WEIGHT: Final[float] = 0.10 LONG_PAYLOAD_WEIGHT: Final[float] = 0.20 WORKER_COUNT: Final[int] = 4 QUEUE_SIZE: Final[int] = 128 # ============================================================ # DATA MODELS # ============================================================ @dataclass(frozen=True) class PolicyResult:     allowed: bool     status: str     risk_score: float @dataclass(frozen=True) class Telemetry:     budget_ms: float     entropy: float     risk_score: float @dataclass(frozen=True) class ExecutionResult:     status: int     session_id: str     telemetry: dict     forensic_sig: str     auth_tag: 